--
-- Table structure for table `spell_levels`
--

DROP TABLE IF EXISTS `spell_levels`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8mb4 */;
CREATE TABLE `spell_levels` (
  `Id` bigint(20) NOT NULL,
  `SpellId` smallint(6) DEFAULT NULL,
  `Grade` tinyint(4) DEFAULT NULL,
  `SpellBreed` smallint(6) DEFAULT NULL,
  `ApCost` smallint(6) DEFAULT NULL,
  `MinRange` smallint(6) DEFAULT NULL,
  `MaxRange` smallint(6) DEFAULT NULL,
  `CastInLine` mediumtext DEFAULT NULL,
  `CastInDiagonal` mediumtext DEFAULT NULL,
  `CastTestLos` mediumtext DEFAULT NULL,
  `CriticalHitProbability` bigint(20) DEFAULT NULL,
  `NeedFreeCell` mediumtext DEFAULT NULL,
  `NeedTakenCell` mediumtext DEFAULT NULL,
  `NeedFreeTrapCell` mediumtext DEFAULT NULL,
  `RangeCanBeBoosted` mediumtext DEFAULT NULL,
  `MaxStack` int(11) DEFAULT NULL,
  `MaxCastPerTurn` bigint(20) DEFAULT NULL,
  `MaxCastPerTarget` int(11) DEFAULT NULL,
  `MinCastInterval` int(11) DEFAULT NULL,
  `InitialCooldown` bigint(20) DEFAULT NULL,
  `GlobalCooldown` int(11) DEFAULT NULL,
  `MinPlayerLevel` int(11) DEFAULT NULL,
  `HideEffects` mediumtext DEFAULT NULL,
  `Hidden` mediumtext DEFAULT NULL,
  `StatesCriterion` varchar(255) DEFAULT NULL,
  `Effects` blob DEFAULT NULL,
  `CriticalEffects` blob DEFAULT NULL,
  PRIMARY KEY (`Id`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci ROW_FORMAT=DYNAMIC;
/*!40101 SET character_set_client = @saved_cs_client */;

